import{_ as p,a0 as a,w as l,s as f,ao as n,I as r,x as o,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"淺議 Firefox 多賬户容器 | LCTT x X-CMD","titleTemplate":false,"description":"淺議 Firefox 多賬户容器 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"淺議 Firefox 多賬户容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"淺議 Firefox 多賬户容器 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20210809 What is Firefox Multi-Account Containers- Why and How to Use It","title":"淺議 Firefox 多賬户容器","tag":"202208","desc":""},"relativePath":"202208/20210809 What is Firefox Multi-Account Containers- Why and How to Use It.md","filePath":"[post].md"}'),m={name:"202208/20210809 What is Firefox Multi-Account Containers- Why and How to Use It.md"};function u(d,t,x,g,C,h){const e=a("Link");return l(),f("div",null,[t[21]||(t[21]=n('<h1 id="淺議-firefox-多賬户容器" tabindex="-1">淺議 Firefox 多賬户容器 <a class="header-anchor" href="#淺議-firefox-多賬户容器" aria-label="Permalink to “淺議 Firefox 多賬户容器”">​</a></h1><p>隨着在設備上使用各種程序的用户的需求變得越來越複雜，程序本身也需要跟上用户的現實需求和未來期望。</p><p>我發現我每天需要的東西是一個在網頁瀏覽器保持登錄多個賬號的簡單方法。我 <em>可以</em> 根據需要對我的每個賬號進行登錄和註銷操作，但在短時間內切換多個賬號時，這變得非常乏味。</p><p>最初，我使用谷歌瀏覽器，它擁有管理多個帳户的能力。這很有效，但管理起來略顯繁瑣，而且明明只需 <em>一個</em> 谷歌賬號就能搞定的事卻要創建一個新的谷歌賬號來完成，這顯得有點兒笨拙。</p><p>這是我轉而使用 Firefox <ruby>多賬户容器<rt>Multi-Account Containers</rt></ruby> 功能的原因。它不僅比我在谷歌 Chrome 瀏覽器上的設置靈活得多，而且我還使用了由我的瀏覽器開發者自己創建的工具，從而在整體上獲得了更流暢和更簡單的體驗。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Firefox-container.png?resize=800%2C450&amp;ssl=1" alt="Firefox 中的容器圖示"></p><h3 id="firefox-中的多帳户容器是什麼" tabindex="-1">Firefox 中的多帳户容器是什麼？ <a class="header-anchor" href="#firefox-中的多帳户容器是什麼" aria-label="Permalink to “Firefox 中的多帳户容器是什麼？”">​</a></h3><p>如果你想將數字生活的各個部分彼此分開，多賬户容器也非常有效。通過使用容器，你在一個容器中的瀏覽活動不會與其他容器共享。這種隔離意味着你可以在不同容器中登錄同一網站上的兩個不同帳户。你的登錄會話、網站偏好和跟蹤數據將被限制在你使用某個網站的容器中。</p><p>它還有什麼其他優勢？想像一下，你在亞馬遜或其他電子商務網站上購物。你瀏覽了一些商品，但沒有購買任何東西。現在，如果你瀏覽網絡，你會看到與你瀏覽的產品相關的廣告。儘管有廣告攔截器，一些網站仍會顯示廣告。使用容器，你可以將你的購物網站與其他網站分開。（LCTT 校注：甚至根據你的瀏覽歷史，你再次訪問同一網站時看到的價格可能會被“宰熟”——反覆瀏覽代表了你的購買傾向。）</p><p>再給大家分享一個例子。Firefox 默認提供一個 Facebook 容器。默認情況下，此容器包括 Facebook、Messenger 和 Instagram 網站。這意味着當你打開這三個網站中的任何一個時，它們都只會在“Facebook 容器”中打開。因此，Facebook 將無法跟蹤你在其他網站上的活動。</p>',10)),r("p",null,[t[1]||(t[1]=o("這是 ",-1)),s(e,{href:"https://itsfoss.com/firefox-useful-features/"},{default:i(()=>[...t[0]||(t[0]=[o("很少有人知道或使用的 Firefox 功能",-1)])]),_:1}),t[2]||(t[2]=o(" 之一。",-1))]),t[22]||(t[22]=r("h3",{id:"使用多賬户容器",tabindex:"-1"},[o("使用多賬户容器 "),r("a",{class:"header-anchor",href:"#使用多賬户容器","aria-label":"Permalink to “使用多賬户容器”"},"​")],-1)),t[23]||(t[23]=r("p",null,"安裝 Firefox 多賬户容器是一個非常簡單的過程，只需點擊幾下。",-1)),r("p",null,[t[4]||(t[4]=o("首先，前往 Firefox 附加組件網站上的 ",-1)),s(e,{href:"https://addons.mozilla.org/en-US/firefox/addon/multi-account-containers/?utm_source=addons.mozilla.org&utm_medium=referral&utm_content=search"},{default:i(()=>[...t[3]||(t[3]=[o("擴展程序頁面",-1)])]),_:1}),t[5]||(t[5]=o("。之後你唯一需要做的就是單擊 “添加到 Firefox” 按鈕。",-1))]),t[24]||(t[24]=n('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-install-page.png?resize=800%2C366&amp;ssl=1" alt=""></p><p>安裝完成！現在我們可以實際使用一下這個新的擴展。</p><p>可能你還沒有注意到，你的搜索欄右側應該會出現一個新圖標：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-searchbar-icon-1.png?resize=800%2C48&amp;ssl=1" alt=""></p><p>這是你將用於與 Firefox 多帳户容器交互的圖標。如果你單擊該圖標，你將看到一個小菜單：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-main-menu.png?resize=302%2C474&amp;ssl=1" alt=""></p><p>讓我們使用這個擴展嘗試一些例子，看看多賬户容器是如何工作的。</p><h4 id="設置容器" tabindex="-1">設置容器 <a class="header-anchor" href="#設置容器" aria-label="Permalink to “設置容器”">​</a></h4><p>首先，我們需要生成一個容器。點擊多賬户容器菜單中的 `<ruby>管理容器<rt>Manage Containers</rt></ruby>，然後點擊 <ruby>新建容器<rt>New Container</rt></ruby>。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-manage-containers-1.png?resize=291%2C402&amp;ssl=1" alt=""></p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-new-container.png?resize=290%2C399&amp;ssl=1" alt=""></p><p>接着輸入新容器的名稱，選擇顏色和圖標。然後，點擊 “OK” 保存新容器。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-new-container-itsfoss.png?resize=292%2C401&amp;ssl=1" alt=""></p><p>大功告成！我們現在可以返回主菜單在新容器中打開一個新選項卡：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-opening-new-container.png?resize=290%2C398&amp;ssl=1" alt=""></p><p>你還會注意到新選項卡有一些樣式，表示它正在容器內運行：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-new-container-styling.png?resize=800%2C370&amp;ssl=1" alt=""></p><h4 id="觀察容器工作" tabindex="-1">觀察容器工作 <a class="header-anchor" href="#觀察容器工作" aria-label="Permalink to “觀察容器工作”">​</a></h4><p>現在讓我們看看容器在使用時實際做了什麼。</p><p>我們將在一個普通的瀏覽器選項卡中訪問 Linode 管理網站，我已經在其中登錄：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-linode.png?resize=800%2C114&amp;ssl=1" alt=""></p><p>現在讓我們嘗試在 Firefox 容器中打開相同的頁面，此時我被重定向到 Linode 登錄頁面：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-linode-login.png?resize=800%2C405&amp;ssl=1" alt=""></p><p>為什麼我被重定向了？因為現在我沒有登錄。這就是 Firefox 容器的樂趣之一：在一個瀏覽器會話中登錄後，再進入一個容器，就好像你以前從未訪問過該站點一樣。</p><p>如果你在容器內完成對某個網站的登錄，你從容器中訪問該網站時將會保持登錄狀態。你還可以使用此功能從容器內登錄網站，從而使該網站的所有數據與你的正常瀏覽器數據相隔開。</p><blockquote><p>注意：你的瀏覽器歷史記錄本身之類的內容仍會暴露給你的正常瀏覽器會話。容器功能只是提供了一種方法來分離本文中提到的登錄帳户等內容。</p></blockquote><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>對於那些在乎自己的隱私，或者只是想真正嘗試對其系統的安全性進行嚴格控制的人來説，多賬户容器被證明是一個很棒的功能。</p><p>例如，你可以在容器內登錄你的谷歌帳户，谷歌永遠不會知悉你在容器外的信息。 對擁有多個帳户的人來説，此擴展程序是一個不錯的選擇。有了它無需為你要使用的每樣東西創建單獨的瀏覽器帳户。</p><p>好了，這就是 Firefox 的多帳户容器的基本知識。</p><p>需要任何幫助，或者只是有點問題？請隨時在評論區指出。</p><hr>',32)),r("p",null,[t[7]||(t[7]=o("via: ",-1)),s(e,{href:"https://itsfoss.com/firefox-containers/"},{default:i(()=>[...t[6]||(t[6]=[o("https://itsfoss.com/firefox-containers/",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=o("作者：",-1)),s(e,{href:"https://itsfoss.com/author/hunter/"},{default:i(()=>[...t[8]||(t[8]=[o("Hunter Wittenborn",-1)])]),_:1}),t[13]||(t[13]=o(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[9]||(t[9]=[o("lujun9972",-1)])]),_:1}),t[14]||(t[14]=o(" 譯者：",-1)),s(e,{href:"https://github.com/hanszhao80"},{default:i(()=>[...t[10]||(t[10]=[o("hanszhao80",-1)])]),_:1}),t[15]||(t[15]=o(" 校對：",-1)),s(e,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:i(()=>[...t[11]||(t[11]=[o("校對者ID",-1)])]),_:1})]),r("p",null,[t[18]||(t[18]=o("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[o("LCTT",-1)])]),_:1}),t[19]||(t[19]=o(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[o("Linux中國",-1)])]),_:1}),t[20]||(t[20]=o(" 榮譽推出",-1))])])}const b=p(m,[["render",u]]);export{T as __pageData,b as default};
